  for (const [op, opValue] of Object.entries(operators)) {
    switch (op) {
      case '$eq':
        if (!matchesSingleValue(docValue, opValue)) return false;
        break;

      case '$ne':
        if (matchesSingleValue(docValue, opValue)) return false;
        break;

